-- Run after group_raffles.sql against a disposable fully migrated database.
do $$begin if current_database()<>'byus_clean' or inet_server_addr() is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
\ir group_scope_fixture.sql
create function pg_temp.l6_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.l6_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$
declare owner uuid:='e9460000-0000-4000-8000-000000000001';fan uuid:='e9460000-0000-4000-8000-000000000002';departed uuid:='e9460000-0000-4000-8000-000000000003';page uuid:='e9460000-0000-4000-8000-000000000004';raffle uuid;ticket uuid;pending uuid;scheduled uuid;wave uuid;creator uuid;mission uuid;post uuid;input jsonb;result jsonb;since timestamptz:=now()-interval '2 days';cond jsonb;before_balance bigint;notice uuid;
begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:l6-owner','l6-owner@example.test'),(fan,'did:privy:l6-fan','l6-fan@example.test'),(departed,'did:privy:l6-departed','l6-departed@example.test');
 insert into public.group_pages(id,kind,name)values(page,'hobby','L6 fixture');
 insert into public.group_memberships(page_id,app_user_id,role,joined_at)values(page,owner,'owner',since),(page,fan,'member',since),(page,departed,'member',since);
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=current_date;
 perform pg_temp.l6_assert(public.group_raffle_conditions_valid('[{"type":"attendance_days","min":30},{"type":"mission_approved","min":10},{"type":"post_or_comment","min":50}]'),'inclusive upper bounds');
 for cond in select value from jsonb_array_elements('[null,{},[{"type":"attendance_days","min":0}],[{"type":"attendance_days","min":31}],[{"type":"mission_approved","min":11}],[{"type":"post_or_comment","min":51}],[{"type":"post_or_comment","min":1.5}],[{"type":"unknown","min":1}],[{"type":"attendance_days","min":1,"extra":true}]]'::jsonb) loop
  perform pg_temp.l6_assert(not public.group_raffle_conditions_valid(cond),'reject malformed condition '||cond::text);
 end loop;
 insert into public.group_visits(page_id,app_user_id,day)values(page,fan,(since at time zone 'Asia/Seoul')::date-1),(page,fan,(since at time zone 'Asia/Seoul')::date),(page,fan,(now() at time zone 'Asia/Seoul')::date);
 perform pg_temp.l6_assert(public.group_raffle_conditions_met(page,fan,'[{"type":"attendance_days","min":2}]',since) and not public.group_raffle_conditions_met(page,fan,'[{"type":"attendance_days","min":3}]',since),'hobby counts distinct visit dates since joining only');
 wave:=pg_temp.group_scope_fixture(fan,true);select celebrity_id into creator from public.group_pages where id=wave;
 insert into public.group_visits(page_id,app_user_id,day)values(wave,fan,(now() at time zone 'Asia/Seoul')::date);
 perform pg_temp.l6_assert(not public.group_raffle_conditions_met(wave,fan,'[{"type":"attendance_days","min":1}]',since),'fan page does not substitute visits for creator attendance');
 insert into public.group_creator_attendance(app_user_id,celebrity_id,attendance_date,streak,points,request_key,policy_version)values(fan,creator,(now() at time zone 'Asia/Seoul')::date,1,0,extensions.gen_random_uuid(),1);
 perform pg_temp.l6_assert(public.group_raffle_conditions_met(wave,fan,'[{"type":"attendance_days","min":1}]',since),'fan counts creator attendance');
 insert into public.group_missions(page_id,title,instructions,state)values(page,'Fixture mission','Fixture instructions','published')returning id into mission;
 insert into public.group_mission_submissions(mission_id,app_user_id,body,status)values(mission,fan,'Fixture pending','pending');
 perform pg_temp.l6_assert(not public.group_raffle_conditions_met(page,fan,'[{"type":"mission_approved","min":1}]',since),'pending submission is not approved');
 update public.group_mission_submissions set status='completed',reviewed_at=now() where mission_id=mission and app_user_id=fan;
 perform pg_temp.l6_assert(public.group_raffle_conditions_met(page,fan,'[{"type":"mission_approved","min":1}]',since),'completed approved submission counts');
 insert into public.group_posts(page_id,author_id,title,body,visibility,anonymous)values(page,fan,'Fixture','Fixture body','members',false)returning id into post;
 insert into public.group_comments(post_id,author_id,body,anonymous)values(post,fan,'Fixture comment',false);
 perform pg_temp.l6_assert(public.group_raffle_conditions_met(page,fan,'[{"type":"post_or_comment","min":2}]',since),'posts and comments combine');
 update public.group_posts set removed_at=now() where id=post;
 perform pg_temp.l6_assert(not public.group_raffle_conditions_met(page,fan,'[{"type":"post_or_comment","min":1}]',since),'removed posts and their comments do not count');
 input:=jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Public prize','winnerQuantity',2,'perUserLimit',9,'entryMode','free','conditions','[{"type":"attendance_days","min":2}]'::jsonb,'closesAt',clock_timestamp()+interval '1 hour','submissionDays',7,'fulfillmentMethod','digital');
 raffle:=(public.group_raffle_dispatch('create',owner,page,null,input)->>'id')::uuid;
 perform pg_temp.l6_assert((select per_user_limit=1 from public.group_raffles where id=raffle),'free limit forced to one');
 perform pg_temp.l6_error(format('update public.group_raffles set conditions=%L where id=%L','[{"type":"post_or_comment","min":51}]',raffle),'group_raffle_conditions_valid');
 perform pg_temp.l6_error(format('insert into public.group_raffle_entries(raffle_id,app_user_id,request_key,amount,ledger_id) values(%L,%L,%L,1,%L)',raffle,fan,extensions.gen_random_uuid(),extensions.gen_random_uuid()),'INVALID');
 ticket:=(public.group_raffle_dispatch('create',owner,page,null,input||jsonb_build_object('requestId',extensions.gen_random_uuid(),'entryMode','ticket'))->>'id')::uuid;
 perform pg_temp.l6_error(format('insert into public.group_raffle_entries(raffle_id,app_user_id,request_key,amount,ledger_id) values(%L,%L,%L,1,null)',ticket,fan,extensions.gen_random_uuid()),'INVALID');
 result:=public.group_raffle_dispatch('detail',fan,page,raffle);
 perform pg_temp.l6_assert((result->>'canEnter')::boolean and result->'conditionProgress'->0->>'current'='2' and result->'raffle'->>'entryMode'='free' and result->'raffle' ? 'giftSnapshot','detail progress and gift wrapper contract');
 before_balance:=public.group_wallet_balance(fan,'ticket');
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''enter'',%L,%L,%L,%L)',fan,page,raffle,jsonb_build_object('requestId',extensions.gen_random_uuid(),'amount',2)),'LIMIT');
 perform public.group_raffle_dispatch('enter',fan,page,raffle,jsonb_build_object('requestId',extensions.gen_random_uuid(),'amount',1));
 perform pg_temp.l6_assert(public.group_wallet_balance(fan,'ticket')=before_balance and (select amount=1 and ledger_id is null from public.group_raffle_entries where raffle_id=raffle and app_user_id=fan),'free entry has weight one and no wallet debit');
 perform pg_temp.l6_assert(not (public.group_raffle_dispatch('detail',fan,page,raffle)->>'canEnter')::boolean,'cannot enter after free quota used');
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''enter'',%L,%L,%L,%L)',fan,page,raffle,jsonb_build_object('requestId',extensions.gen_random_uuid(),'amount',1)),'LIMIT');
 -- Removed member entered before leaving; neither result nor winner notification may be sent.
 insert into public.group_raffle_entries(raffle_id,app_user_id,request_key,amount,ledger_id)values(raffle,departed,extensions.gen_random_uuid(),1,null);
 delete from public.group_memberships where page_id=page and app_user_id=departed;
 pending:=(public.group_raffle_dispatch('create',owner,page,null,input||jsonb_build_object('requestId',extensions.gen_random_uuid()))->>'id')::uuid;
 update public.group_raffles set approval_status='pending'where id=pending;
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''enter'',%L,%L,%L,%L)',fan,page,pending,jsonb_build_object('requestId',extensions.gen_random_uuid(),'amount',1)),'CLOSED');
 perform pg_temp.l6_assert(not (public.group_raffle_dispatch('detail',fan,page,pending)->>'canEnter')::boolean,'pending cannot enter');
 scheduled:=(public.group_raffle_dispatch('create',owner,page,null,input||jsonb_build_object('requestId',extensions.gen_random_uuid(),'opensAt',clock_timestamp()+interval '30 minutes'))->>'id')::uuid;
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''enter'',%L,%L,%L,%L)',fan,page,scheduled,jsonb_build_object('requestId',extensions.gen_random_uuid(),'amount',1)),'CLOSED');
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''create'',%L,%L,null,%L)',owner,page,input||jsonb_build_object('requestId',extensions.gen_random_uuid(),'opensAt',input->>'closesAt')),'INVALID');
 perform pg_temp.l6_error(format('select public.group_raffle_dispatch(''create'',%L,%L,null,%L)',owner,page,input||jsonb_build_object('requestId',extensions.gen_random_uuid(),'conditions','[{"type":"attendance_days","min":31}]'::jsonb)),'INVALID');
 update public.group_raffles set opens_at=clock_timestamp()-interval '2 hours',closes_at=clock_timestamp()-interval '1 hour'where id in(raffle,pending);
 perform public.process_due_group_raffles();perform public.process_due_group_raffles();
 perform pg_temp.l6_assert((select drawn_at is null from public.group_raffles where id=pending),'unapproved raffle cannot draw');
 perform pg_temp.l6_assert((select count(*) from public.fan_notifications where kind='group_raffle_result' and payload->>'targetId'=raffle::text)=1,'result sends exactly once to current member entrants');
 perform pg_temp.l6_assert(not exists(select 1 from public.fan_notifications where app_user_id=departed and kind::text in('group_raffle_result','group_raffle_won')),'nonmember receives neither result nor winner notification');
 select id into notice from public.fan_notifications where app_user_id=fan and kind='group_raffle_result'and payload->>'targetId'=raffle::text;
 update public.fan_notifications set scheduled_for=now()where id=notice;
 perform pg_temp.l6_assert(public.fan_web_notification_kind('group_raffle_result') and public.fan_web_notification_path(fan,notice)='/pages/groups/'||page||'/raffles/'||raffle,'result kind and direct link are supported');
 insert into public.group_notification_settings(page_id,app_user_id,recipient_enabled)values(page,fan,false)on conflict(page_id,app_user_id)do update set recipient_enabled=false;
 perform pg_temp.l6_assert(public.fan_web_notification_path(fan,notice) is null and not public.group_notification_allowed(fan,'group_raffle_result','group_raffle',raffle),'result honors per-page recipient preference');
 update public.group_notification_settings set recipient_enabled=true,enabled=false where page_id=page and app_user_id=fan;
 perform pg_temp.l6_assert(public.fan_web_notification_path(fan,notice) is null,'result honors whole-page notification optout');
 update public.group_notification_settings set enabled=true where page_id=page and app_user_id=fan;
 perform pg_temp.l6_assert((select payload->>'prizeName'='Public prize' and not(payload ? 'nickname') from public.fan_notifications where id=notice),'result body stores prize name without member identity');
 insert into public.user_profiles(app_user_id,nickname)values(fan,'Private full nickname'),(departed,'Departed private name')on conflict(app_user_id)do update set nickname=excluded.nickname;
 result:=public.group_raffle_dispatch('detail',fan,page,raffle);
 perform pg_temp.l6_assert(jsonb_array_length(result->'winnersMasked')=2 and (select bool_and(length(value)=2 and right(value,1)='*') from jsonb_array_elements_text(result->'winnersMasked')),'member winner names expose only one character');
 update public.group_raffles set results_public=false where id=raffle;
 perform pg_temp.l6_assert(jsonb_array_length(public.group_raffle_dispatch('detail',fan,page,raffle)->'winnersMasked')=0,'results_public suppresses masked names');
 perform pg_temp.l6_assert(jsonb_array_length(public.group_raffle_dispatch('detail',departed,page,raffle)->'winnersMasked')=0,'nonmember cannot see winner names');
 delete from public.group_memberships where page_id=page and app_user_id=fan;
 perform pg_temp.l6_assert(public.fan_web_notification_path(fan,notice) is null,'leaving also removes result link');
 perform pg_temp.l6_assert(not has_function_privilege('authenticated','public.group_raffle_condition_progress(uuid,uuid,jsonb,timestamptz)','EXECUTE') and not has_function_privilege('service_role','public.group_raffle_notify_result()','EXECUTE'),'internal helpers are not public APIs');
end $$;
rollback;
